oxy_webhelp_navlinks = {"mdb_physic_br_req_rsc_perms-d39307e36681":{"topics":[{"title":"Application configuration for Ops Manager","shortdesc":"<p class=\"shortdesc\">Application configuration for physical backup and recovery using Ops Manager provides         guidelines for configuring Ops Manager to support third-party backups. To ensure secure and         efficient backup management within Ops Manager, you must configure it with TLS encryption, a         Backup Admin API key, and specific key-value pairs.<\/p>","href":"mongodb\/app_config_ops_manager.html","attributes":{"data-id":"app_config_ops_manager"},"menu":{"hasChildren":false},"tocID":"app_config_ops_manager-d39307e36698","topics":[]}]}};